lines = []
for line in raw_data.strip().split('\\n'):
    parts = [p.strip() for p in line.split('\\t') if p.strip()]
    if len(parts) >= 18:
        lines.append(','.join(parts))

header = "#,Name,Team,K/9 K/9 - Strikeouts per 9 Innings ((SO*9)/IP),BB/9 BB/9 - Walks per 9 Innings ((BB*9)/IP),K/BB K/BB - Strikeout to Walk Ratio (SO/BB),HR/9 HR/9 - Home Runs per 9 Innings ((HR*9)/IP),K% K% - Strikeout Percentage (SO/TBF),BB% BB% - Walk Percentage (BB/TBF),K-BB% K-BB% - The difference between strikeout percentage and walk percentage,AVG AVG - Batting Average Against,WHIP WHIP - Walks + Hits divided by Innings Pitched,BABIP BABIP - Batting Average on Balls in Play,LOB% LOB% - Left on Base Percentage,ERA- ERA- - ERA adjusted for park and league where 100 is average and lower is better,FIP- FIP- - FIP adjusted for park and league where 100 is average and lower is better,xFIP- xFIP- - xFIP adjusted by league where 100 is average and lower is better,ERA ERA - Earned Run Average ((ER*9)/IP),FIP FIP - Fielder Independent Pitching on an ERA scale,E-F,xFIP xFIP - Expected Fielder Independent Pitching where Home Runs are calculated as 10.5% of Fly Balls induced,SIERA SIERA - Skill Interactive ERA"

with open('/Users/danielreiss/Desktop/Antigravity/MLB/MLB Stats', 'a') as f:
    f.write('\\nPitching Advanced,,,,,,,,,,,,,,,,,,,,,\\n')
    f.write(header + '\\n')
    for line in lines:
        f.write(line + '\\n')

print("SUCCESS: New Pitching Advanced data appended.")
